#!/usr/bin/env python3
"""fix_act_3_visuals.py -- Three-Act Evolution, part 3 of 4: card faces.

Needs fix_act_2_engine.py first. Ports the approved preview onto the real
board: Act II cracked frame, Act III gilt proscenium and curtains, stage
badge, TRAGIC tag, passive tag (glows when live), stacked edges for earlier
stages, the evolve drop-in, Act cards in hand, and the Act III gate modal
styling. Additive only. Refuses to run twice. Writes a .bak.
"""
import os, shutil, sys
SRC="src/game.src.html"
MARK="/* ===== Three-Act Evolution (Act cards) ===== */"
CSS='/* ===== Three-Act Evolution (Act cards) ===== */\n.act-badge{ position:absolute; top:5px; left:5px; z-index:6; font-family:var(--cond); font-size:9px; line-height:1; letter-spacing:1px;\n  padding:3px 6px; border-radius:5px; font-weight:800; box-shadow:0 1px 3px rgba(0,0,0,.45); }\n.act-badge.a2{ background:linear-gradient(90deg,#5a1414,#8c2a20,#5a1414); color:#f6dcd4; }\n.act-badge.a3{ background:linear-gradient(90deg,#caa53a,#f5e08a,#caa53a); color:#3a2b06; text-shadow:0 1px 0 rgba(255,255,255,.35); }\n.act-res{ position:absolute; top:5px; right:5px; z-index:6; font-family:var(--cond); font-size:9px; letter-spacing:1px; padding:3px 6px;\n  border-radius:5px; background:#1a0e10; color:#e9b3aa; border:1px solid #8c2a20; }\n.act-res.comic{ background:#123322; color:#cfeecf; border-color:#3f6c3a; }\n.act-pass{ position:absolute; left:5px; bottom:5px; z-index:6; max-width:calc(100% - 40px); white-space:nowrap; overflow:hidden; text-overflow:ellipsis;\n  font-family:var(--cond); font-size:9.5px; letter-spacing:.6px; padding:3px 7px; border-radius:6px; background:rgba(26,14,16,.88); color:#f5c16c; border:1px solid #8c2a20; cursor:help; }\n.act-pass.live{ border-color:#f5c16c; box-shadow:0 0 0 2px rgba(245,193,108,.35); color:#ffe3a3; }\n/* Act II: the frame darkens and cracks -- conflict has marked the character */\n.char.act2{ --frame:#0c0506; --paper:#e2cbc4; box-shadow:0 -6px 0 -2px #d4bdb6, 0 -6px 0 0 #3a1a1a, 0 3px 0 rgba(40,25,12,.45), 0 5px 12px rgba(40,25,12,.18); }\n.char.act2 .pc-art{ filter:contrast(1.06) saturate(.92); }\n.act-crack{ position:absolute; inset:0; width:100%; height:100%; z-index:4; pointer-events:none; }\n.act-crack path{ fill:none; stroke:rgba(236,200,190,.8); stroke-width:1.4; stroke-linecap:round; stroke-linejoin:round; vector-effect:non-scaling-stroke; }\n/* Act III: gilt proscenium and tied-back curtains -- the climax is staged */\n.char.act3{ --frame:#7a5a14; --paper:#f1e2c0; border-color:#b8902c;\n  box-shadow:0 -12px 0 -4px #d4bdb6, 0 -12px 0 -2px #3a1a1a, 0 -6px 0 -2px #e2cbc4, 0 -6px 0 0 #3a1a1a,\n             0 0 0 2px #3a2806, 0 0 0 4px #e3c35a, 0 4px 0 #3a2806, 0 10px 24px rgba(160,110,20,.35); }\n.char.act3 .pc-art{ border-color:#b8902c; box-shadow:inset 0 0 0 2px #f5e08a; }\n.act-curtain{ position:absolute; top:0; bottom:0; width:12%; z-index:3; pointer-events:none;\n  background:repeating-linear-gradient(90deg,#6e0f14 0 5px,#9c1c22 5px 9px,#5a0b10 9px 12px); box-shadow:inset 0 -8px 10px rgba(0,0,0,.35); }\n.act-curtain.l{ left:0; border-bottom-right-radius:100% 62%; }\n.act-curtain.r{ right:0; border-bottom-left-radius:100% 62%; }\n.act-valance{ position:absolute; left:0; right:0; top:0; height:12px; z-index:4; pointer-events:none;\n  background:radial-gradient(circle at 9px -2px,#9c1c22 8px,transparent 9px) 0 0/18px 12px repeat-x, linear-gradient(#6e0f14,#6e0f14) 0 0/100% 4px no-repeat;\n  border-bottom:1px solid rgba(245,224,138,.5); }\n/* the evolution moment */\n@keyframes actEvoDrop{ 0%{ transform:translateY(-40px) scale(1.08) rotate(-2deg); opacity:0; filter:brightness(1.8); }\n  55%{ transform:translateY(4px) scale(.98); opacity:1; filter:brightness(1.25); } 100%{ transform:none; filter:none; } }\n.char.evo-in{ animation:actEvoDrop .62s cubic-bezier(.2,.9,.25,1.2) both; }\n@media (prefers-reduced-motion: reduce){ .char.evo-in{ animation:none; } }\n/* Act cards in hand ride on the character hand card */\n.act-hc .hc-top.act2t{ background:linear-gradient(90deg,#5a1414,#8c2a20); color:#f6dcd4; }\n.act-hc .hc-top.act3t{ background:linear-gradient(90deg,#b8902c,#f5e08a); color:#3a2b06; }\n.act-cond{ font-family:var(--cond); font-size:9px; letter-spacing:.5px; text-align:center; padding:3px 5px; border-top:1px dashed #c9b58a; }\n.act-cond.met{ color:#1f6a3a; } .act-cond.unmet{ color:#8c2a20; }\n/* the Act III gate */\n.trivia.climax .tri-head{ background:linear-gradient(90deg,#6e0f14,#9c1c22 50%,#6e0f14); color:#f5e08a; border-bottom:3px solid #caa53a; }\n.gate-tag{ display:inline-block; font-family:var(--cond); font-size:10px; letter-spacing:1px; padding:2px 7px; border-radius:5px; margin-left:6px; vertical-align:middle; }\n.gate-tag.climax{ background:#9c1c22; color:#f5e08a; } .gate-tag.theme{ background:#1F6A6A; color:#FBF3DD; } .gate-tag.story{ background:#3a322b; color:#FBF3DD; }\n.tri-opt.gate-wrong{ background:#f2c2bc; border-color:#8C2A20; text-decoration:line-through; opacity:.8; }\n.tri-opt.gate-right{ background:#cfe8cf; border-color:#1f6a3a; }\n.gate-foot{ padding:0 16px 16px; display:flex; justify-content:flex-end; }\n'
JS='/* ---- Three-Act Evolution: card-face pieces (badge, frame dressing, passive tag) ---- */\nfunction actArt(ch){\n  if(!ch||!(ch.act>1)) return \'\';\n  ch._evoFx=false;\n  const live=!!(ch.passive&&ch.passive.lowHpAtkAdd&&ch.hp>0&&ch.hp<ch.maxHp/2);\n  const dress = ch.act===3\n    ? \'<span class="act-curtain l"></span><span class="act-curtain r"></span><span class="act-valance"></span>\'\n    : \'<svg class="act-crack" viewBox="0 0 200 120" preserveAspectRatio="none" aria-hidden="true"><path d="M1 18 L9 24 L6 33 L15 39"/><path d="M199 8 L190 14 L193 22"/><path d="M40 1 L44 7 L40 12"/><path d="M1 104 L8 99 L7 91"/><path d="M199 112 L191 117"/></svg>\';\n  const pas = ch.passive ? `<span class="act-pass${live?\' live\':\'\'}" title="${(ch.passive.name+\' \\u2014 \'+(ch.passive.text||\'\')).replace(/"/g,\'&quot;\')}">\\u2726 ${ch.passive.name}${live?\' \\u00b7 ACTIVE\':\'\'}</span>` : \'\';\n  return dress+`<span class="act-badge a${ch.act}" title="Act ${roman(ch.act)} \\u2014 evolved from ${actStageName(ch.act===3?(actById(ch._actId)||{}).from:ch.id)}">ACT ${roman(ch.act)}</span>`\n    +(ch.resolution===\'tragic\'?\'<span class="act-res">TRAGIC</span>\':(ch.resolution===\'comic\'?\'<span class="act-res comic">COMIC</span>\':\'\'))+pas;\n}\nfunction actHandCard(c,idx,straty,deal,_lk){\n  const you=S.you, a=actById(c.actId)||{name:c.name||\'Act card\',act:c.act||2};\n  const pk=actPick(you,c), ok=straty && !drawnLocked() && !!pk.t;\n  const img=a.img?`<img class="hcc-img" src="${a.img}" alt="${a.name}" style="object-position:${a.hpos||\'50% 22%\'}">`\n                 :`<span class="hcc-mono" style="background:${a.accent||\'#444\'}">${initials(a.name)}</span>`;\n  const onField=actTargets(you,a).length>0;\n  let met=false, cond=\'\';\n  if(a.plot===\'hit\'){ met=actTargets(you,a).some(function(t){ return t._tookHit; }); cond=\'Plot Point 1 \\u00b7 took damage \'+(met?\'\\u2713\':\'\\u2717\'); }\n  else { met=onField; cond=\'Plot Point 2 \\u00b7 climax or theme question\'; }\n  return `<div class="hc crit act-hc ${ok?\'playable\':\'spent\'}${deal}${_lk}" data-idx="${idx}" title="${(ok?\'Tap to evolve\':pk.why).replace(/"/g,\'&quot;\')}">\n      <div class="hc-top crt act${a.act}t">\\u2605 ACT ${roman(a.act)}</div>\n      <div class="hcc-port">${img}</div>\n      <div class="hcc-nm">${a.name}</div>\n      <div class="hcc-foot">Evolves from ${actStageName(a.from)}</div>\n      <div class="act-cond ${met?\'met\':\'unmet\'}">${cond}</div></div>`;\n}\nfunction actHandInfo(c){\n  const a=actById(c.actId); if(!a) return \'\';\n  const pk=actPick(S.you,c); let out=\'\';\n  out+=\'<div class="hvi-row th"><b>\\u2605 Act \'+roman(a.act)+\' \\u2014 evolves from \'+actStageName(a.from)+\'</b><p>\'\n     +(a.plot===\'hit\'?\'Plot Point 1: the character must have taken damage.\':\'Plot Point 2: answer a climax or theme question correctly (one try per turn).\')\n     +\' Not on the turn it entered play. Damage and charges carry over; statuses clear.\'+(pk.t?\'\':\' <i>\'+pk.why+\'</i>\')+\'</p></div>\';\n  out+=\'<div class="hvi-row"><b>\\u2764 Health</b><p>\'+a.hp+\' HP</p></div>\';\n  if(a.atk) out+=\'<div class="hvi-row"><b>\\u2694 \'+a.atk.n+\' \\u2014 \'+(a.atk.label||\'\')+\'</b><p>\'+(a.atk.t||\'\')+\'</p></div>\';\n  if(a.blk) out+=\'<div class="hvi-row"><b>\\u26ca \'+a.blk.n+\' \\u2014 \'+(a.blk.label||\'\')+\'</b><p>\'+(a.blk.t||\'\')+\'</p></div>\';\n  if(a.passive) out+=\'<div class="hvi-row th"><b>\\u2726 \'+a.passive.name+\'</b><p>\'+(a.passive.text||\'\')+\'</p></div>\';\n  return \'<div class="hv-info">\'+out+\'</div>\';\n}\n'
EDITS=[('CSS', '</style>', '__CSS__</style>'), ('visual helpers', 'function charTile(p,side){', '__JS__\nfunction charTile(p,side){'), ('charTile: Act frame classes', "${ch.fe?' fe':''}${ch._boss?' boss':''}", "${ch.fe?' fe':''}${ch.act>1?' act'+ch.act:''}${ch._evoFx?' evo-in':''}${ch._boss?' boss':''}"), ('charTile: Act art pieces', '<div class="pc-art">${port}', '<div class="pc-art">${actArt(ch)}${port}'), ('handCard: Act cards', '  const playable=straty && (you.flags.bmCount||0)<2 && !drawnLocked();\n', "  if(c.cat==='act') return actHandCard(c,idx,straty,deal,_lk);\n  const playable=straty && (you.flags.bmCount||0)<2 && !drawnLocked();\n"), ('hand view: Act card rules', "  if(c.cat==='bookmark'){\n    var t=c.text||c.desc||'';", "  if(c.cat==='act') return actHandInfo(c);\n  if(c.cat==='bookmark'){\n    var t=c.text||c.desc||'';")]
def die(m): sys.exit("[fix_act_3_visuals] ABORT: "+m)
if not os.path.exists(SRC): die(SRC+" not found -- run from the repo root")
s=open(SRC,encoding="utf-8").read()
if MARK in s: die("already applied")
if "/* ---------------- THREE-ACT EVOLUTION (Act cards) ----------------" not in s: die("run fix_act_2_engine.py first")
for label,a,r in EDITS:
    n=s.count(a)
    if n!=1: die("anchor for '%s' found %d times (need 1)"%(label,n))
shutil.copyfile(SRC,SRC+".bak")
for label,a,r in EDITS:
    s=s.replace(a,r.replace("__CSS__",CSS).replace("__JS__",JS),1)
open(SRC,"w",encoding="utf-8").write(s)
print("[fix_act_3_visuals] OK -- %d edits applied"%len(EDITS))
